#[path="../src/wallpaper_model.rs"]mod wallpaper_model;
#[path="../src/permissions.rs"]mod permissions;
use wallpaper_model::*;
#[test]fn request_layout_and_preference_roundtrip(){assert_eq!(core::mem::size_of::<Request>(),112);let mut r=Request::new();let path=b"/PICS/PHOTO.BMP";r.path[..path.len()].copy_from_slice(path);r.length=path.len() as u16;r.mode=1;r.volume=77;let mut b=[0;128];let n=r.encode(&mut b);let parsed=Request::parse(&b[..n]).unwrap();assert_eq!(parsed.mode,1);assert_eq!(&parsed.path[..parsed.length as usize],path);assert_eq!(parsed.volume,0);let r=Request::new();let n=r.encode(&mut b);assert_eq!(Request::parse(&b[..n]),Some(r));}
#[test]fn malformed_config_and_paths_refused(){for path in [b"relative.bmp" as &[u8],b"/../A.BMP",b"/PICS//A.BMP",b"/A\\B.BMP",b"/TOOLONGNAME.BMP",b"/A.BMP/",b"/A:BAD.BMP",b"/A.BMP ARG"]{assert!(!valid_path(path));}for b in [b"bad" as &[u8],b"XINYI-WALL 1\n3\n/A.BMP\n",b"XINYI-WALL 1\n0\n/A.BMP",b"XINYI-WALL 1\n0\n/A.BMP\nextra\n"]{assert!(Request::parse(b).is_none());}let mut r=Request::new();r.length=u16::MAX;assert!(!r.valid());}
#[test]fn fit_fill_and_center_geometry(){let p=Placement::new(4,2,8,8,0).unwrap();assert_eq!((p.x,p.y,p.width,p.height),(0,2,8,4));assert_eq!(p.source(0,0),(0,0));assert_eq!(p.source(7,3),(3,1));let p=Placement::new(4,2,8,8,1).unwrap();assert_eq!((p.x,p.y,p.width,p.height),(0,0,8,8));assert_eq!(p.source(0,0),(1,0));assert_eq!(p.source(7,7),(2,1));let p=Placement::new(4,2,8,8,2).unwrap();assert_eq!((p.x,p.y,p.width,p.height),(2,3,4,2));let p=Placement::new(10,6,4,2,2).unwrap();assert_eq!(p.source(0,0),(3,2));assert_eq!(p.source(3,1),(6,3));}
#[test]fn every_sample_stays_inside_image_and_workspace(){for (sw,sh) in [(1,1),(2048,1),(1,2048),(640,400),(800,600)]{for (dw,dh) in [(800,544),(1280,960)]{for mode in 0..3 {let p=Placement::new(sw,sh,dw,dh,mode).unwrap();assert!(p.x+p.width<=dw&&p.y+p.height<=dh);for (x,y) in [(0,0),(p.width-1,p.height-1),(p.width/2,p.height/2)]{let(sx,sy)=p.source(x,y);assert!(sx<sw&&sy<sh);}}}}assert!(Placement::new(0,2,800,544,0).is_none());assert!(Placement::new(2,2,800,544,3).is_none());}
#[test]fn restricted_profiles_can_query_but_not_replace_wallpaper(){use permissions::Profile::*;for profile in [ReadOnly,Media,Isolated]{assert!(profile.allows(106,0));for op in 1..=4{assert!(!profile.allows(106,op));}}assert!(Trusted.allows(106,2));}
